13	/**
14	 * The stock ledger.
15	 *
16	 * The ledger counts units, not promises: a row knows that twelve units are
17	 * held, and nothing more. Which reservation holds them is the reservations
18	 * table's business, and that asymmetry is what the `release` contract below is
19	 * about.
20	 */
21	export class InventoryRepo extends BaseRepo {
22	  constructor(
23	    db: Db,
24	    private readonly clock: Clock,
25	  ) {
26	    super(db);
27	  }
28	
29	  async find(warehouseId: WarehouseId, sku: Sku): Promise<InventoryItem | null> {
30	    const row = this.rowIn(this.db.read().inventory, warehouseId, sku);
31	    return row === undefined ? null : toInventoryItem(row);
32	  }
33	
34	  async listForWarehouse(warehouseId: WarehouseId): Promise<InventoryItem[]> {
35	    return this.db
36	      .read()
37	      .inventory.filter((row) => row.warehouse_id === warehouseId)
38	      .map(toInventoryItem);
39	  }
