41	  /**
42	   * Promises `units` of a sku to a reservation, failing if they are not there.
43	   */
44	  async holdWithin(tx: Tx, warehouseId: WarehouseId, sku: Sku, units: number): Promise<void> {
45	    const row = this.requireRowIn(tx.tables.inventory, warehouseId, sku);
46	    const item = toInventoryItem(row);
47	    if (availableUnits(item) < units) {
48	      throw new InsufficientStockError(sku, units, availableUnits(item));
49	    }
50	    row.held += units;
51	    row.updated_at = this.clock.now();
52	  }
53	
54	  /**
55	   * Returns `units` of held stock to the available pool.
56	   *
57	   * The ledger records how many units are held, never *which* reservation is
58	   * holding them, so this method cannot distinguish a second release of the
59	   * same units from a first: both are a subtraction it will happily perform.
60	   * Exactly one release per hold is therefore the caller's obligation. A
61	   * second one does not fail — it quietly overstates availability, and the row
62	   * oversells the next time someone asks for stock that is not there.
63	   */
64	  async releaseWithin(tx: Tx, warehouseId: WarehouseId, sku: Sku, units: number): Promise<void> {
65	    const row = this.requireRowIn(tx.tables.inventory, warehouseId, sku);
66	    row.held -= units;
67	    row.updated_at = this.clock.now();
68	  }
69	
70	  /** Picking: the units leave the shelf, so they leave both columns. */
71	  async consumeWithin(tx: Tx, warehouseId: WarehouseId, sku: Sku, units: number): Promise<void> {
72	    const row = this.requireRowIn(tx.tables.inventory, warehouseId, sku);
73	    row.on_hand -= units;
74	    row.held -= units;
75	    row.updated_at = this.clock.now();
76	  }
