7	/**
8	 * Drops audit rows past the retention window.
9	 *
10	 * The audit trail is advisory — nothing reads it to make a decision — so rows
11	 * are deleted outright rather than archived.
12	 */
13	export class AuditPruner implements Job {
14	  readonly name = 'audit-prune';
15	
16	  constructor(
17	    private readonly audit: AuditRepo,
18	    private readonly clock: Clock,
19	    private readonly logger: Logger,
20	    private readonly metrics: Metrics,
21	    private readonly config: { intervalMs: number; retentionMs: number },
22	  ) {}
23	
24	  get intervalMs(): number {
25	    return this.config.intervalMs;
26	  }
27	
28	  async runOnce(): Promise<JobRunSummary> {
29	    const cutoff = this.clock.now() - this.config.retentionMs;
30	    const removed = await this.audit.deleteOlderThan(cutoff);
31	    this.metrics.increment('audit.pruned', removed);
32	    this.logger.log('info', 'audit.pruned', { removed, cutoff });
33	    return { processed: removed, failed: 0 };
34	  }
35	}
