5	export interface JobRunSummary {
6	  /** Rows the job successfully dealt with. */
7	  processed: number;
8	  /** Rows it tried and could not. */
9	  failed: number;
10	}
11	
12	export interface Job {
13	  readonly name: string;
14	  readonly intervalMs: number;
15	  runOnce(): Promise<JobRunSummary>;
16	}
17	
18	export const EMPTY_SUMMARY: JobRunSummary = { processed: 0, failed: 0 };
19	
20	/**
21	 * Runs jobs on their own cadence.
22	 *
23	 * A tick that throws is logged and the job stays scheduled: background work is
24	 * retried by definition, and a job that unscheduled itself on the first bad
25	 * row would go quiet exactly when it is most needed.
26	 */
27	export class JobRunner {
28	  private readonly lastRunAt = new Map<string, number>();
29	
30	  constructor(
31	    private readonly jobs: readonly Job[],
32	    private readonly clock: Clock,
33	    private readonly logger: Logger,
34	    private readonly metrics: Metrics,
35	  ) {}
36	
37	  async tick(): Promise<void> {
38	    const now = this.clock.now();
39	    for (const job of this.jobs) {
40	      const last = this.lastRunAt.get(job.name) ?? 0;
41	      if (now - last < job.intervalMs) {
42	        continue;
43	      }
44	      this.lastRunAt.set(job.name, now);
45	      await this.run(job);
46	    }
47	  }
48	
49	  private async run(job: Job): Promise<void> {
50	    try {
51	      const summary = await job.runOnce();
52	      this.metrics.increment(`job.${job.name}.processed`, summary.processed);
53	      this.metrics.increment(`job.${job.name}.failed`, summary.failed);
54	      this.logger.log('info', 'job.completed', { job: job.name, ...summary });
55	    } catch (error) {
56	      this.metrics.increment(`job.${job.name}.crashed`);
57	      this.logger.log('error', 'job.crashed', { job: job.name, ...describeError(error) });
58	    }
59	  }
60	}
